struct queue { pthread_mutex_t m; pthread_cond_t cv; job_t *head, *tail; size_t n, cap; } q;
void dispatch(job_t *j) {                       /* one owner of the dequeue step */
    pthread_mutex_lock(&q.m);
    while (q.n == q.cap) pthread_cond_wait(&q.cv, &q.m);   /* bounded: block */
    push(&q, j);
    pthread_cond_signal(&q.cv);
    pthread_mutex_unlock(&q.m);
}
void *performer(void *_) { for (;;) { job_t *j = take(&q); if (!j) return NULL; handle(j); } }
